use formora::scene::Scene;
fn main(){let scene=Scene::load(std::path::Path::new(&std::env::args().nth(1).unwrap())).unwrap();let camera=formora::preview::math::camera(&scene,640,480).unwrap();let vertices=formora::preview::math::vertices(&scene).unwrap();let result:Vec<_>=vertices.iter().map(|v|{let p=glam::DVec3::from_array(v.position.map(f64::from));let clip=camera.view_projection*glam::DVec4::new(p.x,p.y,p.z,1.);serde_json::json!({"position":v.position,"screen":[(clip.x/clip.w+1.)*320.,(1.-clip.y/clip.w)*240.],"color":v.color})}).collect();println!("{}",serde_json::to_string(&result).unwrap());}
